/**
 * Buy the Field
 * -------------
 * In the besieged city Jeremiah buys a field at Anathoth and seals the deed, for the Lord promises houses and fields will again be bought. Stage: a walled city under siege at dusk, a deed being sealed and buried in an earthen jar, a field beyond the walls; a candle in a siege lamp.
 *
 * Palette 0x1a0e08 → 0x060402 · light: dusk · hero: jar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, cityGate, house, wheat, jar, person, birds } from './jeremiah-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3996408503, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [10, 0, -58], { name: 'city', r: [0, -0.14, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x1d0f09, head: 0x21120a });

    /* hero: the jar */
    jar(W, group, 0, 0, 0, 1.25, { clay: 0x050402 });
    W.disc([0, 4, -10], 4, 0x22120a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e1009, wrapTrim: 0x120a06, beard: 'long', ry: -0.12, s: 1.04 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e1009, wrapTrim: 0x120a06, beard: 'long', ry: -0.06, s: 1.13 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e1009, wrapTrim: 0x120a06, beard: 'long', ry: 0.31, s: 1.00 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
